import {useState,useRef,useEffect} from'react';
export function useCompletion(){
 const [completion,setCompletion]=useState(''),[isLoading,setLoading]=useState(false);
 const job=useRef<any>(null),alive=useRef(true);
 const cancel=()=>{if(job.current){clearTimeout(job.current.timer);job.current.resolve('');job.current=null}if(alive.current)setLoading(false)};
 useEffect(()=>{alive.current=true;const hide=()=>{if(document.hidden)cancel()};document.addEventListener('visibilitychange',hide);return()=>{alive.current=false;cancel();document.removeEventListener('visibilitychange',hide)}},[]);
 const complete=(_text:string,_options:any)=>{
  cancel();setCompletion('');setLoading(true);
  return new Promise<string>(resolve=>{
   job.current={resolve,timer:setTimeout(()=>{
    job.current=null;if(!alive.current||document.hidden){resolve('');return}
    const result='This is a prerecorded local example. Review the draft, confirm the important details, and choose the next action.';
    setCompletion(result);setLoading(false);resolve(result);
   },240)};
  });
 };
 return{completion,isLoading,complete};
}
